// Code node "Plan ticket"  (mode: Run Once for Each Item)   [only runs when jira_enabled is true]
// Input : the answer of "Jira search" (open issues with the contract's label). The contract comes from "Claim alert".
// Output: { create, existing_key, jira_note, ticket } -> "Create ticket?" -> "Jira create".
// Rules:
//   - an open issue with the contract label exists -> reuse its key, never create a second one
//   - the search itself failed -> do NOT create (we cannot tell if one exists), say so in the note
//   - no open issue -> create one, but only at the first (largest) threshold, the 90-day mark

const contract = $('Claim alert').item.json;
const cfg = $('Config').first().json.cfg;
const search = $json;

if (search.error) {
  return { json: { create: false, existing_key: null, jira_note: `Jira search failed: ${search.error.message ?? search.error}` } };
}
const found = (search.issues ?? [])[0];
if (found) return { json: { create: false, existing_key: found.key, jira_note: null } };

const first = Math.max(...(cfg.renewal_thresholds ?? [90]));
if (contract.threshold_days !== first) {
  return { json: { create: false, existing_key: null, jira_note: null } };
}

const tool = `${contract.tool} (${contract.contract_ref})`;
const money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
const ticket = {
  fields: {
    project: { key: cfg.jira_project_key },
    issuetype: { name: cfg.jira_issue_type ?? 'Task' },
    summary: `Renewal review: ${tool}, notice by ${String(contract.notice_deadline).slice(0, 10)}`,
    description: `Contract ${contract.contract_ref} for ${contract.tool} (${contract.vendor}) ends on ${String(contract.end_date).slice(0, 10)}.\n`
      + `Notice deadline: ${String(contract.notice_deadline).slice(0, 10)} (${contract.days_left} days).\n`
      + `Seats: ${contract.seats} · annual value ${money.format(contract.annual_value)}\n`
      + `Owner: ${contract.owner_email}\n\nPlease review usage and decide: renew, resize or cancel.\nCreated automatically by n8n (workflow D).`,
    labels: [contract.contract_ref, 'license-renewal'],
  },
};
return { json: { create: true, existing_key: null, jira_note: null, ticket } };

// Code node "Build alert"  (mode: Run Once for Each Item)
// Input : $json is one of
//   - the claimed alert itself (Jira is off),
//   - "Plan ticket" output with an existing key or a note (no new ticket needed),
//   - the answer of "Jira create" ({ key } or { error }).
// Output: { contract_id, threshold_days, ticket_key, text, blocks } for the Slack node.

const c = $('Claim alert').item.json;
const money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
const day = (value) => String(value).slice(0, 10);

let ticketKey = $json.key ?? $json.existing_key ?? '';
let jiraNote = $json.jira_note ?? '';
if ($json.error) jiraNote = `Jira ticket could not be created: ${$json.error.message ?? $json.error}`;

const overdue = c.days_left < 0;
const when = overdue
  ? `notice deadline *passed ${-c.days_left} days ago* (${day(c.notice_deadline)})`
  : `notice deadline in *${c.days_left} days* (${day(c.notice_deadline)})`;
const outcome = c.auto_renew ? 'renews automatically unless cancelled' : 'expires unless renewed';

const lines = [
  `:alarm_clock: *${c.tool}* (${c.vendor}), contract ${c.contract_ref}: ${when}`,
  `The contract ends ${day(c.end_date)} and ${outcome}.`,
];
const blocks = [
  { type: 'section', text: { type: 'mrkdwn', text: lines.join('\n') } },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*Seats*\n${c.seats}` },
      { type: 'mrkdwn', text: `*Annual value*\n${money.format(c.annual_value)} (${c.billing_cycle})` },
      { type: 'mrkdwn', text: `*Owner*\n${c.owner_email}` },
      { type: 'mrkdwn', text: `*Alert level*\n${c.threshold_days}-day notice` },
    ],
  },
];
const context = [];
if (ticketKey) context.push({ type: 'mrkdwn', text: `:ticket: Renewal review: *${ticketKey}*` });
if (jiraNote) context.push({ type: 'mrkdwn', text: `:warning: ${jiraNote}` });
if (context.length) blocks.push({ type: 'context', elements: context });

return {
  json: {
    contract_id: c.contract_id,
    threshold_days: c.threshold_days,
    contract_ref: c.contract_ref,
    ticket_key: ticketKey,
    text: `${c.tool} (${c.contract_ref}): notice deadline ${overdue ? 'passed' : `in ${c.days_left} days`}`,
    blocks,
  },
};

// Ends the run as failed when a Slack alert could not be sent, so the error workflow alerts.
if ($('Release claim').isExecuted) {
  throw new Error(`Renewal alert not sent: ${$('Release claim').all().length} contract(s) will be retried on the next run (see dead_letter)`);
}
return $input.all();
